  internal static string Get(string key,int languageId)
  {
   if(key==null)return String.Empty;
   string[] values;
   if(!Text.TryGetValue(key,out values))return key;
   if(languageId<0||languageId>=Names.Length)languageId=0;
   if(languageId==18)return Xiongxin.OWTS.Localization.UiLanguage.ToTraditional(values[0]);
   string localized;if(Xiongxin.OWTS.Localization.UiLanguage.TryTranslate(languageId,values[1],out localized))return localized;
   return values[Xiongxin.OWTS.Localization.UiLanguage.LegacyIndex(languageId)];
  }
